Use a hashmap + doubly linked list. The list maintains order (most recently used at front), the hashmap gives O(1) access.

```cpp
class LRUCache {
    int capacity;
    list<pair<int,int>> lru;  // {key, value}
    unordered_map<int, list<pair<int,int>>::iterator> map;
public:
    LRUCache(int cap) : capacity(cap) {}

    int get(int key) {
        if (!map.count(key)) return -1;
        lru.splice(lru.begin(), lru, map[key]);  // move to front
        return map[key]->second;
    }

    void put(int key, int value) {
        if (map.count(key)) lru.erase(map[key]);
        lru.push_front({key, value});
        map[key] = lru.begin();
        if (lru.size() > capacity) {
            map.erase(lru.back().first);
            lru.pop_back();
        }
    }
};
```
